class Solution {
public:
    int minOperations(string initial, string target) {
        int n = initial.size(), m = target.size(), best = 0;
        vector<int> dp(m + 1);
        for (int i = 1; i <= n; ++i) {
            for (int j = m; j >= 1; --j) {
                dp[j] = initial[i - 1] == target[j - 1] ? dp[j - 1] + 1 : 0;
                best = max(best, dp[j]);
            }
        }
        return n + m - 2 * best;
    }
};
